          concept: 'sliding window rate limiting',
          language: 'javascript',
          starter: "function allowRequests(times, limit, windowSize) {\n  const accepted = [];\n  const results = [];\n  for (const time of times) {\n    let recent = 0;\n    for (const t of accepted) {\n      if (t > time - windowSize) recent++;\n    }\n    if (recent < limit) {\n      accepted.push(time);\n      results.push(true);\n    } else {\n      results.push(false);\n    }\n  }\n  return results;\n}",
          solution: "function allowRequests(times, limit, windowSize) {\n  const hits = [];\n  const results = [];\n  for (const time of times) {\n    while (hits.length > 0 && hits[0] <= time - windowSize) hits.shift();\n    if (hits.length < limit) {\n      hits.push(time);\n      results.push(true);\n    } else {\n      results.push(false);\n    }\n  }\n  return results;\n}",
